-- Whiplash injury exaggerated for months of compensation
INSERT INTO reference_fraud_case
  (case_id, title, description, is_confirmed, is_active, embedding_model_id, embedding, created_by)
VALUES (
  'c2000000-0000-0000-0000-000000000009',
  'Whiplash injury exaggerated for months of compensation',
  'Following a gentle bump in slow traffic, the claimant reported severe neck and back pain, months of physiotherapy and loss of income. Social media posts during the same period showed him lifting weights and playing cricket, and the physiotherapy centre billed sessions on days it was closed.',
