-- Burglary staged to claim jewellery that was never owned
INSERT INTO reference_fraud_case
  (case_id, title, description, is_confirmed, is_active, embedding_model_id, embedding, created_by)
VALUES (
  'c2000000-0000-0000-0000-000000000012',
  'Burglary staged to claim jewellery that was never owned',
  'The household reported a break-in and listed gold jewellery and electronics worth several lakh rupees. The window had been broken from the inside, purchase invoices were generated on the same day by a single shop, and the neighbours heard nothing although a dog was kept in the yard.',
