-- Car abandoned and torched to escape loan payments
INSERT INTO reference_fraud_case
  (case_id, title, description, is_confirmed, is_active, embedding_model_id, embedding, created_by)
VALUES (
  'c2000000-0000-0000-0000-000000000015',
  'Car abandoned and torched to escape loan payments',
  'An owner behind on EMI payments reported his hatchback stolen, and it was found burnt out at a quarry a week later. The keys were never handed over, the fuel tank had been drained beforehand, and the car had been advertised for sale at a price far below the outstanding loan.',
